CREATE  PROCEDURE [dbo].[DEAD_HEAD_PRINT3]  AS SELECT        dbo.DEAD_DTL_PRINT.DATE_S, dbo.DEAD_DTL_PRINT.SHARH_S, dbo.DEAD_DTL_PRINT.HES, dbo.DEAD_DTL_PRINT.TNUMBER,                         dbo.DEAD_DTL_PRINT.NUMBER, dbo.DEAD_DTL_PRINT.HNAME, dbo.DEAD_DTL_PRINT.TNAME, dbo.DEAD_DTL_PRINT.MNAME,                         dbo.DEAD_DTL_PRINT.KNAME, dbo.DEAD_DTL_PRINT.N_KOL, dbo.DEAD_DTL_PRINT.BED, dbo.DEAD_DTL_PRINT.BES, dbo.DEAD_DTL_PRINT.SHARH,                         dbo.DEAD_DTL_PRINT.kk, dbo.DEAD_DTL_PRINT.BASE, dbo.DEAD_DTL_PRINT.RADIF, dbo.DEAD_DTL_PRINT.GR, dbo.DEAD_DTL_PRINT.N_S,                         dbo.DEAD_WITHSUM.SUMOFBED, dbo.DEAD_WITHSUM.SumOfBES, dbo.DEAD_DTL_PRINT.BED + dbo.DEAD_DTL_PRINT.BES AS JOZ,                         dbo.UIIF(dbo.DEAD_WITHSUM.SUMOFBED, N'>', 0, dbo.DEAD_WITHSUM.SUMOFBED * 1000 + dbo.DEAD_DTL_PRINT.N_KOL, dbo.DEAD_WITHSUM.SumOfBES * - 1000 - dbo.DEAD_DTL_PRINT.N_KOL) AS GRPAS, dbo.DEAD_DTL_PRINT.UNAME, dbo.DEED_HED.SGN1,                         dbo.DEED_HED.SGN2, dbo.DEED_HED.SGN3, dbo.DEED_HED.SGN4, dbo.DEED_HED.sgn1usid, dbo.DEED_HED.sgn2usid, dbo.DEED_HED.sgn3usid,                         dbo.SALA_DTL.EMZA AS EMZA1, SALA_DTL_2.EMZA AS EMZA3, SALA_DTL_1.EMZA AS EMZA2 FROM            dbo.SALA_DTL AS SALA_DTL_2 RIGHT OUTER JOIN                         dbo.DEAD_DTL_PRINT INNER JOIN                         dbo.DEAD_WITHSUM ON dbo.DEAD_DTL_PRINT.GR = dbo.DEAD_WITHSUM.GR AND dbo.DEAD_DTL_PRINT.N_KOL = dbo.DEAD_WITHSUM.N_KOL AND                         dbo.DEAD_DTL_PRINT.N_S = dbo.DEAD_WITHSUM.N_S INNER JOIN                         dbo.DEED_HED ON dbo.DEAD_DTL_PRINT.N_S = dbo.DEED_HED.N_S ON SALA_DTL_2.IDD = dbo.DEED_HED.sgn3usid LEFT OUTER JOIN                         dbo.SALA_DTL AS SALA_DTL_1 ON dbo.DEED_HED.sgn2usid = SALA_DTL_1.IDD LEFT OUTER JOIN  dbo.SALA_DTL ON dbo.DEED_HED.sgn1usid = dbo.SALA_DTL.IDD 
